#include <stdio.h>
#include <math.h>

const char* discriminant(double val, double other, double c) {
    if (val == other) {
        return "equal_inputs";
    }
    double d = other * other - 4.0 * val * c;
    if (d > 0.0) {
        return "two_real";
    } else if (d == 0.0) {
        return "one_real";
    } else {
        return "complex";
    }
}

int main() {
    printf("%s\n", discriminant(1.0, 2.0, 1.0));
    printf("%s\n", discriminant(1.0, 3.0, 2.0));
    printf("%s\n", discriminant(1.0, 1.0, 1.0));
    printf("%s\n", discriminant(0.0, 2.0, 3.0));
    printf("%s\n", discriminant(1.0, 0.0, 1.0));
    return 0;
}

