import java.util.*;

public class Solution {
    public static String discriminant(double val, double other, double c) {
        if (val == other) {
            return "equal_inputs";
        }
        double d = other * other - 4.0 * val * c;
        if (d > 0.0) {
            return "two_real";
        }
        if (d == 0.0) {
            return "one_real";
        }
        return "complex";
    }

    public static void main(String[] args) {
        System.out.println(discriminant(1.0, 2.0, 3.0));
        System.out.println(discriminant(1.0, 4.0, 4.0));
        System.out.println(discriminant(1.0, 1.0, 1.0));
        System.out.println(discriminant(0.0, 5.0, 2.0));
        System.out.println(discriminant(2.0, 2.0, 2.0));
    }
}
